INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-27', 'es', 'LAIKA 64 3.6.3: adiós a los falsos DESINCRONIZADO', 'Tras una espera larga en línea ya no aparece DESINCRONIZADO cuando el juego sigue igual en todas las consolas. El log muestra qué consola frena la partida. Ahora puedes enviar mensajes a cualquier jugador, sea tu amigo o no. Actualiza desde LAIKA.'),
 ('2026-11-27', 'en', 'LAIKA 64 3.6.3: no more false DESYNC warnings', 'After a long online wait, DESINCRONIZADO no longer shows while the game is the same on every console. The log shows which console slows the game down. You can now send messages to any player, friend or not. Update from LAIKA.'),
 ('2026-11-27', 'pt', 'LAIKA 64 3.6.3: adeus aos falsos DESINCRONIZADO', 'Depois de uma espera longa online, DESINCRONIZADO não aparece mais quando o jogo segue igual em todos os consoles. O log mostra qual console deixa a partida lenta. Agora você pode enviar mensagens a qualquer jogador, amigo ou não. Atualize pelo LAIKA.'),
 ('2026-11-27', 'fr', 'LAIKA 64 3.6.3 : fini les faux DÉSYNCHRONISÉ', 'Après une longue attente en ligne, DESINCRONIZADO ne s''affiche plus quand la partie reste la même sur toutes les consoles. Le journal montre quelle console ralentit la partie. Tu peux maintenant écrire à n''importe quel joueur, ami ou non. Mets à jour depuis LAIKA.'),
 ('2026-11-27', 'de', 'LAIKA 64 3.6.3: keine falschen DESYNC-Meldungen mehr', 'Nach langem Warten online erscheint DESINCRONIZADO nicht mehr, wenn das Spiel auf allen Konsolen gleich ist. Das Protokoll zeigt, welche Konsole das Spiel bremst. Du kannst jetzt jedem Spieler schreiben, ob Freund oder nicht. Aktualisiere in LAIKA.'),
 ('2026-11-27', 'it', 'LAIKA 64 3.6.3: basta falsi DESINCRONIZZATO', 'Dopo una lunga attesa online, DESINCRONIZADO non appare più quando la partita è uguale su tutte le console. Il log mostra quale console rallenta la partita. Ora puoi scrivere a qualsiasi giocatore, amico o no. Aggiorna da LAIKA.'),
 ('2026-11-27', 'ru', 'LAIKA 64 3.6.3: без ложных «рассинхронов»', 'После долгого ожидания в сети DESINCRONIZADO больше не появляется, если игра одинакова на всех консолях. В журнале видно, какая консоль тормозит игру. Теперь можно писать любому игроку, даже не другу. Обновись из LAIKA.');
